@once
<style>
.pc-workspace{--pc-ink:#1d3f34;--pc-muted:#687c72;--pc-border:#dce7df;max-width:1232px;width:100%;margin:0 auto;display:grid;gap:24px;color:var(--pc-ink);min-width:0}.pc-workspace *{box-sizing:border-box}.pc-workspace>*{min-width:0;max-width:100%}.pc-workspace [hidden]{display:none!important}.pc-workspace h1,.pc-workspace h2,.pc-workspace h3,.pc-workspace p{margin:0}.pc-heading{display:flex;justify-content:space-between;gap:24px;align-items:flex-start}.pc-heading h1{font-size:29px;line-height:1.25;font-weight:650;letter-spacing:-.8px;margin:6px 0 10px;overflow-wrap:anywhere}.pc-heading p,.pc-help{font-size:13px;line-height:1.75;color:var(--pc-muted)}.pc-kicker{font-size:10px;font-weight:700;letter-spacing:1.4px;color:#60836d;line-height:1.8}.pc-nav{display:flex;gap:7px;overflow-x:auto;max-width:100%;padding:7px;background:#edf2eb;border-radius:14px}.pc-nav a{flex-shrink:0;white-space:nowrap;padding:11px 14px;border-radius:9px;font-size:12px;font-weight:550;color:var(--pc-muted)}.pc-nav a[aria-current=page]{background:#fff;color:#154b37;box-shadow:0 2px 8px #223d3310}.pc-card{background:#fff;border:1px solid var(--pc-border);border-radius:18px;padding:26px;min-width:0}.pc-card h2{font-size:19px;font-weight:650;letter-spacing:-.4px;line-height:1.4;margin-bottom:6px}.pc-card h3{font-size:15px;font-weight:650;line-height:1.5}.pc-section-title{display:flex;gap:13px;align-items:flex-start;margin-bottom:22px}.pc-step{display:grid;place-items:center;flex-shrink:0;width:31px;height:31px;background:#eaf2e6;color:#407045;border-radius:10px;font-size:12px;font-weight:700}.pc-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.pc-field{display:flex;flex-direction:column;gap:7px;font-size:13px;font-weight:600;min-width:0}.pc-field input:not([type=checkbox]):not([type=radio]),.pc-field select,.pc-field textarea,.pc-search{width:100%;min-width:0;border:1px solid #ccd9ce;border-radius:10px;padding:12px 13px;background:#fcfdfb;color:var(--pc-ink);font-size:14px;font-weight:400;line-height:1.5}.pc-field textarea{resize:vertical;min-height:100px}.pc-field small,.pc-muted{font-size:12px;font-weight:400;color:var(--pc-muted);line-height:1.65}.pc-field input:read-only{background:#f1f4ee}.pc-workspace input[type=checkbox],.pc-workspace input[type=radio]{accent-color:#1a684b;width:16px;height:16px;flex-shrink:0}.pc-workspace :focus-visible{outline:2px solid #388b60;outline-offset:3px}.pc-workspace .pc-field-error{color:#b03f38;font-size:12px;font-weight:400}.pc-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:24px;align-items:start}.pc-stack{display:grid;gap:22px;min-width:0}.pc-aside{position:sticky;top:100px}.pc-aside h2{font-size:17px}.pc-aside ol{padding-left:20px;margin:15px 0;font-size:13px;line-height:2}.pc-button{display:inline-flex;justify-content:center;align-items:center;gap:7px;background:#175a42;border:1px solid #175a42;color:#fff;border-radius:11px;padding:12px 17px;font-size:13px;line-height:1.4;font-weight:600;text-align:center;cursor:pointer;text-decoration:none;min-height:43px}.pc-secondary{background:#fff;border-color:#ccdacf;color:#254e3b}.pc-danger{background:#fff3f0;border-color:#f1d0c8;color:#9c3f32}.pc-button:disabled{opacity:.55;cursor:not-allowed}.pc-actions{display:flex;flex-wrap:wrap;gap:11px;align-items:center}.pc-savebar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap;background:#f1f6ed;border:1px solid #d5e4cc;border-radius:14px;padding:18px}.pc-alert{padding:16px 18px;border-radius:12px;font-size:13px;line-height:1.75;background:#f2f6ed;border:1px solid #d5e3ce}.pc-error{background:#fff2ef;color:#953c31;border-color:#ebc9c2}.pc-error ul{margin:7px 0 0;padding-left:18px}.pc-success{background:#eaf7ed;color:#27623c;border-color:#bbdbc5}.pc-warning{background:#fff8e9;color:#825b2a;border-color:#ead9b4}.pc-details{background:#fff;border:1px solid var(--pc-border);border-radius:16px;padding:21px}.pc-details>summary{font-size:15px;font-weight:650;cursor:pointer;line-height:1.5}.pc-details[open]>summary{margin-bottom:20px}.pc-details>summary small{display:block;font-weight:400;font-size:12px;color:var(--pc-muted);margin-top:5px}.pc-chips{display:flex;gap:8px;flex-wrap:wrap}.pc-chip{display:inline-flex;align-items:center;border:1px solid var(--pc-border);background:#fff;padding:10px 13px;border-radius:10px;gap:8px;font-size:13px;cursor:pointer}.pc-chip:has(input:checked){background:#eaf5e7;border-color:#78a37d;color:#225734}.pc-badge{display:inline-block;padding:5px 9px;border-radius:8px;font-size:11px;background:#edf3e8;color:#48683e;font-weight:600;line-height:1.5}.pc-options-group{padding:18px 0;border-bottom:1px solid var(--pc-border)}.pc-options-group:last-child{border-bottom:0}.pc-options-group h3{margin-bottom:12px}.pc-options-top{display:flex;justify-content:space-between;gap:16px;align-items:center}.pc-spec-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;gap:10px;align-items:start;margin-top:12px}.pc-link{color:#21744f;text-decoration:underline;text-underline-offset:3px;font-size:12px;font-weight:600}.pc-picture{display:grid;place-items:center;min-height:190px;border:1px dashed #c5d7c1;border-radius:14px;background:#f1f5ec;color:#7b9274;font-size:13px;overflow:hidden}.pc-picture img{display:block;width:100%;height:230px;object-fit:contain;padding:10px}.pc-summary{display:grid;grid-template-columns:200px minmax(0,1fr);gap:25px}.pc-summary img{width:100%;height:180px;object-fit:contain;border-radius:13px;background:#f4f6ee}.pc-price{font-size:27px;font-weight:650;letter-spacing:-.7px;margin-top:8px!important}.pc-stat-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.pc-stat{background:#f5f8f1;border:1px solid var(--pc-border);border-radius:12px;padding:18px}.pc-stat strong{display:block;font-size:23px;line-height:1.3}.pc-stat span{font-size:12px;color:var(--pc-muted)}.pc-scroll{overflow:auto}.pc-table{width:100%;border-collapse:collapse;text-align:left;font-size:13px}.pc-table th{font-size:10px;text-transform:uppercase;letter-spacing:.8px;color:var(--pc-muted);background:#f7f9f3;padding:14px 12px;font-weight:650}.pc-table td{padding:17px 12px;border-bottom:1px solid var(--pc-border);vertical-align:top}.pc-table td p{font-size:12px;margin-top:5px;color:var(--pc-muted)}.pc-form-list{display:grid;gap:18px}.pc-form-list .pc-card{padding:20px}.pc-variant-header{display:flex;justify-content:space-between;gap:15px;align-items:center;flex-wrap:wrap}.pc-toast{position:fixed;bottom:24px;right:24px;max-width:min(420px,calc(100vw - 32px));padding:16px 20px;border-radius:12px;background:#7c342e;color:white;z-index:100;font-size:13px;line-height:1.6;box-shadow:0 8px 28px #0002}.pc-workspace input[type=file]{font-size:12px}.pc-workspace .pc-span{grid-column:1/-1}.pc-compare{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.pc-compare>div{padding:16px;background:#f5f8f0;border-radius:12px}.pc-compare p{font-size:12px;color:var(--pc-muted);line-height:1.7;margin-top:6px}.dark .pc-workspace{--pc-ink:#deeee3;--pc-muted:#a4bbad;--pc-border:#405c4a}.dark .pc-card,.dark .pc-details,.dark .pc-chip,.dark .pc-secondary,.dark .pc-field input:not([type=checkbox]),.dark .pc-field select,.dark .pc-field textarea{background:#20352b;color:var(--pc-ink)}.dark .pc-nav,.dark .pc-compare>div,.dark .pc-stat,.dark .pc-picture,.dark .pc-savebar{background:#294330}.dark .pc-nav a[aria-current=page]{background:#3b5a45;color:#eaf5eb}
@media(max-width:1100px){.pc-layout{grid-template-columns:minmax(0,1fr)}.pc-aside{position:static}.pc-aside ol{display:flex;gap:30px;flex-wrap:wrap}}@media(max-width:600px){.pc-heading{flex-direction:column;gap:13px}.pc-heading h1{font-size:25px}.pc-card{padding:19px}.pc-grid,.pc-compare,.pc-stat-grid{grid-template-columns:minmax(0,1fr)}.pc-summary{grid-template-columns:1fr}.pc-summary img{height:190px}.pc-spec-row{grid-template-columns:minmax(0,1fr)}.pc-spec-row button{justify-self:start}.pc-savebar .pc-actions,.pc-savebar .pc-button{width:100%}.pc-workspace{gap:18px}.pc-options-top{align-items:flex-start;flex-direction:column}.pc-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.pc-table{min-width:530px}.pc-aside ol{display:block}}
</style>
@endonce
